import React from "react";
import { useState, useEffect, useRef } from "react";
import { useForm } from "react-hook-form";
import { toast } from "react-toastify";
import Select from "react-select";
import Button from "react-bootstrap/Button";
import { useSearchParams, useNavigate } from "react-router-dom";
import { generateUUID, compressBase64, decompressBase64 } from "../../components/utilities/utils";
import { GetLedgerList } from "../dataservice/getLedgerList";
import { GetBranchLedgerMapping } from "../dataservice/getBranchLedgerMapping";
import apiAcc from "../../components/api/AccWebcall";
import api from "../../components/api/Webcall";
import appsettings from "../../appsettings.json"
import { GetBranchList } from "../dataservice/getBranchList";
const apiendpoints = appsettings.ApiEndpoints;

function BranchAccountHeadMap() {

    const navigate = useNavigate();
    const { register, getValues, setValue, reset } = useForm();
    const [searchParams, setSearchParams] = useSearchParams();

    let norPP = useRef(10);
    const [norSkip, setNorSkip] = useState(0);

    const [branchid, setBranchId] = useState(0);
    const [branches, setBranches] = useState([]);
    const [ledgers, setLedgers] = useState(null);
    const [mappedLedgers, setMappedLedgers] = useState(null);

    const fetctBranches = async () => {
        let frmData = {};
        const res = await GetBranchList(frmData);
        if (res) {
            if (res.hdr) {
                if (res.hdr.rst && res.hdr.rst !== "SUCCESS") {
                    if (res.fdr) {
                        setTimeout(() => {

                            let strMsg = "";
                            res.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                            toast.error(strMsg);

                        }, 300);
                    }
                }
                else {
                    if (res.body) {

                        if (res.body.Branches) {
                            const branch = [];
                            res.body.Branches.map((data, i) => {
                                if (data.CoBrStatusId === 1) {
                                    branch.push({ value: data.BranchId, label: data.Name });
                                }
                            });
                            setBranches(branch);
                        }

                    }
                }
            }
        }
    }

    const fetctLedgers = async () => {
        let frmData = {};
        frmData["lgronly"] = true;
        const res = await GetLedgerList(frmData);
        if (res) {
            if (res.hdr) {
                if (res.hdr.rst && res.hdr.rst !== "SUCCESS") {
                    if (res.fdr) {
                        setTimeout(() => {

                            let strMsg = "";
                            res.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                            toast.error(strMsg);

                        }, 300);
                    }
                }
                else {
                    if (res.body) {

                        if (res.body.ledgers) {
                            setLedgers(res.body.ledgers);
                        }

                    }
                }
            }
        }
    }


    const fetctBranchLedgerMap = async (branchid) => {
        let frmData = {};
        frmData["cmbBranchId"] = branchid;
        const res = await GetBranchLedgerMapping(frmData);
        if (res) {
            if (res.hdr) {
                if (res.hdr.rst && res.hdr.rst !== "SUCCESS") {
                    if (res.fdr) {
                        setTimeout(() => {

                            let strMsg = "";
                            res.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                            toast.error(strMsg);

                        }, 300);
                    }
                }
                else {
                    if (res.body) {

                        let mapedlgr = [];
                        ledgers.map((data, i) => {
                            mapedlgr = [...mapedlgr, { lgid: data.lgid, lgna: data.lgna, curr: data.curr, selected: false }];
                        });

                        if (res.body.mappedledgers) {
                            res.body.mappedledgers.map((data, i) => {
                                mapedlgr.find(x => x.lgid === data.lgid)["selected"] = true;
                            });
                        }

                        setMappedLedgers(mapedlgr);
                    }
                }
            }
        }
    }


    const onChange_cmbBranchId = (obj) => {
        setBranchId(obj.value);
        fetctBranchLedgerMap(obj.value);
    }


    const onChange_Selection = (lgid, e) => {
        let mapedlgr = [...mappedLedgers];
        mapedlgr.find(x => x.lgid == lgid).selected = e.target.checked;
        setMappedLedgers(mapedlgr);
    }


    const saveMapping = (e) => {

        let ledgerIds = [];
        mappedLedgers.map((data) => {
            if (data.selected === true) {
                ledgerIds = [...ledgerIds, data.lgid];
            }
        });
        
        let frmData = {};
        frmData["cmbBranchId"] = branchid;
        frmData["txtLedgerIds"] = ledgerIds;

        const convID = generateUUID();
        const frmHdr = { convid: convID, tag: "Save Branch Ledger Mapping", orgid: "", vendid: "_Acc" };
        const data = { hdr: frmHdr, body: frmData };
        const reqHdr = {};
        apiAcc.post(apiendpoints.UpdBrchLgrMap, compressBase64(data), reqHdr)
            .then(function (response) {
                const res = JSON.parse(decompressBase64(response.data));
                if (res) {
                    if (res.hdr) {
                        if (res.hdr.rst && res.hdr.rst !== "SUCCESS") {
                            if (res.fdr) {
                                setTimeout(() => {
                                    let strMsg = "";
                                    res.fdr.map((data) => { strMsg += data.rstmsg + ", " });
                                    toast.error(strMsg);
                                }, 300);
                            }
                        }
                        else {
                            setTimeout(() => { toast.success("Successfully submited"); }, 300);
                        }

                        e.target.disabled = false;
                    }
                }
            });
    }


    /*  Use Effect */
    useEffect(() => {
        fetctBranches();
        fetctLedgers();
    }, []);


    return (

        <>

            <div className="row pad-top-0-5em pad-left-15 pad-right-15">

                <div className="card-header">

                    <strong className="card-title">Branch and Account Head Mapping</strong>

                    <div className="row">

                        <div className="col-md-4">
                            <Select {...register("cmbBranchId")} options={branches} value={branches.find(x => x.value === branchid)}
                                onChange={e => onChange_cmbBranchId(e)}> </Select>
                        </div>

                        <div className="col-md-2">

                            <button className="btn btn-hover color-5 btn-sm  m-2" type="button"
                                onClick={(e) => { saveMapping(e); e.target.disabled = true; }} >
                                Save
                            </button>
                        </div>

                    </div>

                </div>

            </div>



            <div className="row pad-top-0-5em pad-left-15 pad-right-15">

                <div className="col-md-6">

                    <div className="row">

                        <table className="lst-grid">
                            <thead>
                                <tr>
                                    <th>Selcet</th>
                                    <th>Id</th>
                                    <th>Not Mapped Account Heads</th>
                                    <th>Currency</th>
                                </tr>
                            </thead>
                            <tbody>

                                {(mappedLedgers !== null) ?
                                    mappedLedgers.map((data, i) => {
                                        return (
                                            <tr className="ledger-row">
                                                <td align="center">
                                                    <input type="checkbox" checked={data["selected"]}
                                                        onChange={(e) => {
                                                            onChange_Selection(data["lgid"], e);

                                                        }} ></input>
                                                </td>
                                                <td>{data["lgid"]}</td>
                                                <td>{data["lgna"]}</td>
                                                <td align="center">{data["curr"]}</td>
                                            </tr>
                                        )
                                    })
                                    : <tr> <td colSpan={4}> &nbsp; </td> </tr>
                                }

                            </tbody>
                        </table>

                    </div>
                </div>

            </div>

        </>
    );
}

export default BranchAccountHeadMap;
