import { generateUUID, compressBase64, decompressBase64 } from "../../components/utilities/utils";
import api from "../../components/api/Webcall";
import appsettings from "../../appsettings.json"

const apiendpoints = appsettings.ApiEndpoints;

export const GetBranchList = async (frmData) => {

    let Response;

    const convID = generateUUID();
    const frmHdr = { convid: convID, tag: "Ledger List", orgid: "", vendid: "_Acc" };
    const data = { hdr: frmHdr, body: frmData };

    const reqHdr = {};

    await api.post(apiendpoints.BranchList, compressBase64(data), reqHdr)
        .then(function (response) {
            const strResponse = JSON.parse(decompressBase64(response.data));
            Response = strResponse;
        });

    return Response;

};
